package dev.bosatsu

import scala.concurrent.ExecutionContext.Implicits.global
import scala.concurrent.Future
import scala.concurrent.duration.DurationInt

class NestedMatchInferenceTest extends munit.FunSuite {
  // Checking a match branch used to also infer the branch, only to have its
  // type for an error message, so every branch body was type checked twice.
  // That is exponential in how deeply matches nest inside branches, and an
  // if/elif chain nests one match per elif: protobuf decoders generated by
  // `tool protoc-plugin` took minutes to check, doubling with each field. With
  // the old behavior the chain below would never finish; now it takes well
  // under a second. The Future lets the timeout fail the test on the JVM
  // instead of hanging it.
  override val munitTimeout = 1.minute

  // The shape of a generated decoder: a local loop with unannotated
  // parameters whose body is a long if/elif chain of nested matches.
  private def elifChain(depth: Int): String = {
    val branches = (1 to depth).map { i =>
      val keyword = if (i == 1) "if" else "elif"
      val update =
        if (i % 2 == 1) "case IntField(i): loop(tail, i, b)"
        else "case StrField(s): loop(tail, a, s)"
      s"""        $keyword cmp_Int(n, $i) matches EQ:
         |          match v:
         |            $update
         |            case _: None""".stripMargin
    }

    s"""enum FieldValue:
       |  IntField(value: Int)
       |  StrField(value: String)
       |
       |def decode(fields: List[(Int, FieldValue)]) -> Option[(Int, String)]:
       |  def loop(fields, a, b) -> Option[(Int, String)]:
       |    loop fields:
       |      case []: Some((a, b))
       |      case [(n, v), *tail]:
       |${branches.mkString("\n")}
       |        else:
       |          loop(tail, a, b)
       |  loop(fields, 0, '')
       |""".stripMargin
  }

  test("a 40-deep if/elif chain type checks in linear time") {
    Future(TestUtils.checkLast(elifChain(40))(_ => ()))
  }
}
